        v2momMethod: "Service Cloud",
        version: "service",
        details: {
            overview: "Moving the execution of the Push Timeout functionality to server side, as today it happens client side. The Problem Client side execution causes us a few problems Push Timeout doesn't work for mobile users Timing issues caused by network latency - some reporting times are a few seconds off General stability & performance - ends up in an unnecessary round trips from server to client The Solution When Push Timeout is enabled for a given user or on a Service Channel, then the work is automatically time out on the server, even if the work never arrives at the client, the client loses connectivity or the user had closed the browser tab Push timeout continues to fire as expected Work is re-routed as appropriate, including for Messaging Voice All other channels Enhanced Omni-Channel only - standard Omni is unaffected Push timeout works for mobile Accepting/declining work on the client that has already been declined server side is handled gracefully, and work removed from the client with info message",
            keyFeatures: [],
            impact: ""
        },
